/**
 * Ready-to-run commands on a finding, generated by the owning plugin from the
 * stored fields, plus a Terraform hint for IaC-managed resources. Shared by
 * every surface that offers them (sleep schedules, savings findings, ...).
 *
 * The hand-written spec's `FindingRemediation` component is nullable and
 * carries the commitments wording, because zod-to-openapi registered the
 * component from its nullable use there; it is kept exactly so, since every
 * operation referencing it reads the one component.
 */
import { Schema } from "effect";

const RemediationPlaceholder = Schema.Struct({
  name: Schema.String.annotate({
    description: "Shell variable, without the $.",
    examples: ["AWS_PROFILE"],
  }),
  description: Schema.String.annotate({ examples: ["AWS CLI profile for this account"] }),
}).annotate({ identifier: "RemediationPlaceholder" });

const RemediationCommand = Schema.Struct({
  tool: Schema.String.annotate({
    description:
      "CLI the command is written for: aws-cli, gcloud, az, doctl, hcloud, scw, linode-cli, " +
      "oci, kubectl, terraform, confluent, atlas, gh, twilio, snowflake-sql, curl, or a " +
      "plugin's own.",
    examples: ["aws-cli"],
  }),
  command: Schema.String.annotate({
    description: "The command line, values already shell-quoted.",
    examples: [
      'aws ec2 delete-volume --volume-id vol-0a1b2c3d4e5f67890 --region eu-west-1 --profile "$AWS_PROFILE"',
    ],
  }),
  description: Schema.String.annotate({ description: "What the command does." }),
  destructive: Schema.Boolean.annotate({
    description: "True when it deletes data or releases something that cannot be got back.",
  }),
  placeholders: Schema.optionalKey(Schema.Array(RemediationPlaceholder)),
}).annotate({ identifier: "RemediationCommand" });

export const FindingRemediation = Schema.NullOr(
  Schema.Struct({
    commands: Schema.Array(RemediationCommand).annotate({
      description: "In run order; empty when the plugin has nothing to offer for this finding.",
    }),
    placeholders: Schema.Array(RemediationPlaceholder).annotate({
      description: "Every shell variable the commands reference, deduplicated.",
    }),
    iac: Schema.NullOr(
      Schema.Struct({
        address: Schema.String.annotate({ examples: ["aws_instance.api"] }),
        stateLabel: Schema.NullOr(Schema.String),
        attributeChanges: Schema.Array(
          Schema.Struct({
            attribute: Schema.String,
            from: Schema.NullOr(Schema.String).annotate({
              description: "HCL rendering of the current value.",
            }),
            to: Schema.NullOr(Schema.String).annotate({
              description: "HCL rendering of the target value.",
            }),
          }),
        ),
        commands: Schema.Array(RemediationCommand),
      }),
    ).annotate({
      description:
        "Set when IaC reconciliation says Terraform manages the resource: edit the named block " +
        "instead of running the CLI commands, which the next apply would revert.",
    }),
  }),
).annotate({
  identifier: "FindingRemediation",
  description:
    "Idle commitments only: the provider's commands for inspecting and acting on the commitment. Null for the other kinds.",
});
